// Some portions generated by Claude
/** Readable names for blank nodes, whose identifiers mean nothing to a reader and change from query to query. */
import type { Graph } from "./graph-types.ts";
import { humanizeIri } from "./rdf-vocabulary.ts";

const MAX_LENGTH = 60;
export const BLANK_NODE_LABEL = "Blank node";

function short(text: string) {
  const single = text.replace(/\s+/g, " ").trim();
  return single.length > MAX_LENGTH ? `${single.slice(0, MAX_LENGTH - 1)}…` : single;
}

/**
 * The name of every blank node of the graph: its label (a label property's value), else what points at it from a
 * named resource ("address of Bob"), else the statement it is about, else its first value, else "Blank node".
 */
export function blankNodeLabels(graph: Graph, isLabelProperty: (property: string) => boolean) {
  const nodeById = new Map(graph.nodes.map((node) => [node.id, node]));
  const own = new Map<string, string>();
  const pointedAt = new Map<string, string>();
  const firstValue = new Map<string, string>();
  for (const edge of graph.edges) {
    const source = nodeById.get(edge.source);
    const target = nodeById.get(edge.target);
    if (source?.kind === "blank" && target?.kind === "literal") {
      const value = target.termValue ?? target.label;
      if (isLabelProperty(edge.predicate) && !own.has(source.id)) own.set(source.id, value);
      if (!firstValue.has(source.id)) firstValue.set(source.id, value);
    }
    if (target?.kind === "blank" && source && source.kind !== "blank" && !pointedAt.has(target.id))
      pointedAt.set(target.id, `${edge.label} of ${source.label}`);
  }
  // A blank reifier (from `{| … |}` in Turtle) is about a statement: "about Alice works for Acme".
  const about = new Map<string, string>();
  const edgeLabel = new Map(graph.edges.map((edge) => [edge.id, edge.label]));
  for (const link of graph.statementLinks ?? []) {
    if (about.has(link.source) || nodeById.get(link.source)?.kind !== "blank") continue;
    const subject = nodeById.get(link.subject);
    const object = nodeById.get(link.object);
    if (!subject || !object) continue;
    const predicate = edgeLabel.get(link.statementEdgeId) ?? humanizeIri(link.statementPredicate);
    about.set(link.source, `about ${subject.label} ${predicate} ${object.kind === "literal" ? (object.termValue ?? object.label) : object.label}`);
  }
  const labels = new Map<string, string>();
  for (const node of graph.nodes) {
    if (node.kind !== "blank") continue;
    labels.set(
      node.id,
      short(own.get(node.id) ?? pointedAt.get(node.id) ?? about.get(node.id) ?? firstValue.get(node.id) ?? BLANK_NODE_LABEL),
    );
  }
  return labels;
}
